SELECT id, param_key, param_name, param_group, param_value, unit, value_type, description, sort, status, create_time, update_time FROM followup_param WHERE deleted = 0
AND param_key LIKE CONCAT('%', #{query.paramKey}, '%')
AND param_name LIKE CONCAT('%', #{query.paramName}, '%')
AND param_group = #{query.paramGroup}
AND status = #{query.status}
ORDER BY param_group, sort, id

SELECT COUNT(*)
FROM followup_param
WHERE deleted = 0
  AND param_key = #{paramKey}

    AND id != #{excludeId}
